    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","prefix","suffix","label","caption","fromLabel","toLabel","value","decimals","fontWeight","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  prefix: "−",
  suffix: "%",
  label: "less time to a finished cut",
  caption: "vs. keyframing every scene by hand",
  fromLabel: "Before",
  toLabel: "With remocn",
  value: 44,
  decimals: 0,
  fontWeight: 500,
  stagger: 3,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type CutStatElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CutStatBase>;

const CutStatInner = forwardRef<
  HTMLDivElement,
  CutStatElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CutStat>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CutStatBase
          {...(componentProps as unknown as ComponentProps<typeof CutStatBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CutStat = Interactive.withSchema({
  Component: CutStatInner,
  componentName: "<CutStat>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
